  "title": "Teach v2 proposed domain ownership map",
  "type": "object",
  "required": [
    "map_id",
    "version",
    "status",
    "owner",
    "baseline",
    "domains",
    "entries"
  ],
  "properties": {
    "map_id": {
      "const": "TEACH-DOMAIN-OWNERSHIP"
    },
    "version": {
      "type": "string",
      "pattern": "^\\d+\\.\\d+\\.\\d+$"
    },
    "status": {
      "enum": [
        "draft",
        "proposed",
        "active",
        "superseded"
      ]
    },
    "owner": {
      "type": "string",
      "minLength": 1
    },
    "baseline": {
      "type": "object",
      "required": [
        "repo",
        "ref",
        "commit"
      ],
      "properties": {
        "repo": {
          "const": "peteywee/teach-v2"
        },
        "ref": {
