        },
        "commit": {
          "type": "string",
          "pattern": "^[0-9a-f]{40}$"
        }
      },
      "additionalProperties": true
    },
    "domains": {
      "type": "array",
      "minItems": 1
    },
    "entries": {
      "type": "array",
      "minItems": 1
    }
  },
  "additionalProperties": true
}

