{
 "x-document": {
  "doc_id": "TEACH-PROP-DCS-03-DATA",
  "class": "decision-table",
  "version": "0.1.0",
  "status": "proposed",
  "owner": "Patrick Craven, Top Shelf Service LLC",
  "created_on": "2026-10-05",
  "updated_on": "2026-10-05"
 },
 "baseline": {
  "repo": "peteywee/teach-v2",
  "ref": "main",
  "commit": "2b5714d8d850da7a47c1666da5a2c7974cabe40f"
 },
 "resolves_if_approved": [
  "OQ-PRIV-1",
  "OQ-PRIV-2",
  "OQ-PRIV-3",
  "OQ-PRIV-6"
 ],
 "partially_resolves": [
  "OQ-PRIV-4"
 ],
 "remains_unknown": [
  "OQ-PRIV-5"
 ],
 "terms": {
  "DELETED": "Applied to a record: the row is removed from the primary database by a governed, audited executor in a committed transaction, every dependent copy listed in this matrix has its stated expiry action, and the deletion is entered in the deletion ledger. Applied to an Identity: the Identity row becomes the DELETED tombstone (id, status, created_at only) and every personal-data record of the subject is hard-deleted or expired per §4. DELETED is terminal.",
  "ANONYMIZED": "Applies only to aggregate outputs from which no individual record can be recovered, with a minimum cell size of 5 identities per reported group (proposed engineering value). An individual-level record is never called anonymized, regardless of hashing.",
  "PSEUDONYMIZED (technical term, not one of the four)": "Direct identifiers replaced by a value that still allows linkage — opaque IDs while a mapping exists, keyed or unkeyed hashes, payload hashes. Pseudonymized data is personal data. Code and documents MUST NOT call it anonymized.",
  "RETAINED": "The record is kept unchanged, readable only through C14-authorized operations, until its retention clock plus duration elapses; then its expiry action runs. Retention never extends authentication validity.",
  "OFFBOARDED": "Exactly the IDN-18 effects in one transaction: IdentityStatus INACTIVE, IdentityOffboarded emitted, all sessions revoked, frontline credentials and pending single-use tokens revoked, effective Membership and grants removed through the Organization boundary. Offboarding deletes nothing and starts retention clocks."
 },
 "request_lifecycle_states": [
  "RECEIVED",
  "IDENTITY_VERIFIED",
  "SCOPE_CONFIRMED",
  "IN_PROGRESS",
  "ON_HOLD",
  "COMPLETED",
  "REJECTED"
 ],
 "record_classes": [
  {
   "record_class": "Identity",
   "store": "primary-db",
   "physical_state": "IMPLEMENTED_SCHEMA",
   "table": "identity_identities",
   "columns": [
    {
     "name": "id",
     "category": "OPAQUE_ID"
    },
    {
     "name": "status",
     "category": "STATUS"
    },
    {
     "name": "offboarded_at",
     "category": "TIMESTAMP"
    },
    {
     "name": "created_at",
     "category": "TIMESTAMP"
    },
    {
     "name": "updated_at",
     "category": "TIMESTAMP"
    }
   ],
   "owning_domain": "Identity",
   "retention_clock_start": "offboarded_at; for non-offboard deactivation: UNDEFINED (no deactivated_at column)",
   "retention_duration": {
    "value": 1,
    "unit": "year",
    "source": "OWNER_DRAFT_OQ-PRIV-2"
   },
   "expiry_action": "Transition to DELETED tombstone: row kept with id/status/created_at only so immutable audit and lifecycle references stay valid. Requires C11 revision authorizing DELETED ingress solely from the retention/deletion executor (DB trigger currently blocks it).",
   "offboarding_effect": "status INACTIVE, offboarded_at set once, IdentityOffboarded emitted (IDN-18). No data removed.",
   "subject_deletion_action": "Same as expiry action, executed on request after verification (PRIV-11), subject to holds.",
   "legal_hold_effect": "Suspends expiry action and subject deletion for matching rows; does not suspend offboarding, revocation or authentication denial.",
   "subject_deletion_exemption": null,
   "gaps": [
    "No deactivated_at timestamp: retention clock for DeactivateIdentity (non-offboard) cannot start.",
    "DELETED ingress blocked by identity_guard_identity_update trigger; any deletion implementation is BLOCKED until C11 changes."
