              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "closure_class": {
                "enum": [
                  "READY_TO_REGISTER",
                  "REGISTER_WITH_ARTIFACT",
                  "REGISTER_AS_DISABLED",
                  "RECONCILE_DRAFT"
                ]
              }
            }
          },
          "then": {
            "properties": {
              "missing_owner_values": {
                "maxItems": 0
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "live_state": {
                "const": "RESOLVED"
              }
            }
          },
          "then": {
            "properties": {
              "registered_by": {
                "type": "string"
              }
            }
          }
        }
      ]
    }
  }
}

