      "level": "LOGICAL_RECORD_ONLY",
      "approved": [
        "ReconciliationRecord",
        "ReconciliationRecordId",
        "ReconciliationRecordStatus",
        "ExternalEffectOutcome"
      ],
      "blocked_physical_relations": "Provider-specific detail/cardinality is not a new semantic subtype and exact field schema remains implementation design.",
      "persistence_requirements": [
