        "unreadable provider state does not authorize retry"
      ]
    }
  ],
  "blocked_schema_groups": [
    {
      "id": "PER-B01",
      "state": "BLOCKED",
      "group": "strict-nine identifier closure",
      "details": "Nine approved entities still use candidate identifiers."
