    RAISE EXCEPTION 'unsupported Identity lifecycle transition';
  END IF;

  IF OLD."offboarded_at" IS NOT NULL
     AND NEW."offboarded_at" IS DISTINCT FROM OLD."offboarded_at"
  THEN
    RAISE EXCEPTION 'offboarded_at is immutable once set';
