    cwd: new URL('../../', import.meta.url), encoding: 'utf8', timeout: 5000,
  });
}
const holdFixture = (command = 'CreateMembership') => fixture(
  ['commands.json', entry(command, 'command', 'approved', { requires: ['Membership'] })],
